"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type ScrollDrivenAnimationPrimitiveProps = ComponentProps<typeof motion.div>;

export function ScrollDrivenAnimationPrimitive({ children, ...props }: ScrollDrivenAnimationPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {y: 80}}
      animate={{y: -80}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.52, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
